using UnityEngine;
using UnityEngine.InputSystem;
namespace LWS.TruckSports {
public sealed class SportsFrontEnd:SportsMenuView {
 public SportsCatalogue catalogue;
 void FocusScrap()
 {
  var actions=pages[4].GetComponentsInChildren<SportsMenuAction>();
  var cards=System.Array.FindAll(actions,a=>a.action=="wallball"||a.action=="curling"||a.action=="swing"||a.action=="logrolling"||a.action=="dodgeball");
  System.Array.Sort(cards,(a,b)=>Mathf.Abs(a.transform.position.y-b.transform.position.y)>1?b.transform.position.y.CompareTo(a.transform.position.y):a.transform.position.x.CompareTo(b.transform.position.x));
  var back=System.Array.Find(actions,a=>a.action=="scrapback");if(cards.Length==0||back==null)return;
  void Link(UnityEngine.UI.Selectable item,UnityEngine.UI.Selectable up,UnityEngine.UI.Selectable down,UnityEngine.UI.Selectable left,UnityEngine.UI.Selectable right)
  {
   item.navigation=new UnityEngine.UI.Navigation{mode=UnityEngine.UI.Navigation.Mode.Explicit,selectOnUp=up,selectOnDown=down,selectOnLeft=left,selectOnRight=right};
   var heat=item.GetComponent<Michsky.UI.Heat.ButtonManager>();if(heat!=null){heat.navigationMode=UnityEngine.UI.Navigation.Mode.Explicit;heat.selectOnUp=up.gameObject;heat.selectOnDown=down.gameObject;heat.selectOnLeft=left.gameObject;heat.selectOnRight=right.gameObject;}
  }
  var returnButton=back.GetComponent<UnityEngine.UI.Selectable>();
  var items=System.Array.ConvertAll(cards,card=>card.GetComponent<UnityEngine.UI.Selectable>());
  foreach(var button in items)Link(button,Neighbour(button,items,Vector2.up)??button,Neighbour(button,items,Vector2.down)??returnButton,Neighbour(button,items,Vector2.left)??button,Neighbour(button,items,Vector2.right)??button);
  var first=items[0];Link(returnButton,Neighbour(returnButton,items,Vector2.up)??first,first,first,items[items.Length-1]);
  if(UnityEngine.EventSystems.EventSystem.current!=null)UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(first.gameObject);
 }
 public override void Focus(){base.Focus();if(Page==4){FocusScrap();return;}if(Page!=1||pages.Length<2)return;var items=pages[1].GetComponentsInChildren<UnityEngine.UI.Selectable>();foreach(var item in items){var navigation=item.navigation;navigation.selectOnUp=Neighbour(item,items,Vector2.up)??navigation.selectOnUp;navigation.selectOnDown=Neighbour(item,items,Vector2.down)??navigation.selectOnDown;navigation.selectOnLeft=Neighbour(item,items,Vector2.left)??navigation.selectOnLeft;navigation.selectOnRight=Neighbour(item,items,Vector2.right)??navigation.selectOnRight;item.navigation=navigation;var heat=item.GetComponent<Michsky.UI.Heat.ButtonManager>();if(heat!=null){heat.selectOnUp=navigation.selectOnUp?.gameObject;heat.selectOnDown=navigation.selectOnDown?.gameObject;heat.selectOnLeft=navigation.selectOnLeft?.gameObject;heat.selectOnRight=navigation.selectOnRight?.gameObject;}}
  // The legacy hierarchy lists Back before the catalogue. Page changes should
  // enter the newly visible sport grid and update its actual showcase.
  if(catalogue!=null&&UnityEngine.EventSystems.EventSystem.current!=null)foreach(var card in catalogue.cards){if(!card.activeInHierarchy)continue;var choice=card.GetComponentInChildren<SportsCatalogueChoice>();if(choice!=null)UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(choice.gameObject);break;}
 }
 static UnityEngine.UI.Selectable Neighbour(UnityEngine.UI.Selectable from,UnityEngine.UI.Selectable[] items,Vector2 direction){UnityEngine.UI.Selectable nearest=null;float cost=float.MaxValue;foreach(var candidate in items){if(candidate==from||!candidate.IsInteractable())continue;Vector2 delta=candidate.transform.position-from.transform.position;float forward=Vector2.Dot(delta,direction),side=Mathf.Abs(Vector2.Dot(delta,new Vector2(-direction.y,direction.x)));if(forward<=1||side>forward*1.5f)continue;float score=forward+side*3;if(score<cost){cost=score;nearest=candidate;}}return nearest;}
 protected override void Start(){base.Start();SportsNavigation.EnterCollection();Show(SportsNavigation.OpenSelection?1:0);SportsNavigation.OpenSelection=false;}
 public override void Action(string key){if(key=="participants"){GetComponent<SportsParticipantsMenu>().Open();return;}if(key.StartsWith("people")){GetComponent<SportsParticipantsMenu>().Action(key);return;}base.Action(key);if(SportsImpossibleGames.TryFindKey(key,out var impossible)){SportsNavigation.LoadSport(impossible.scene);return;}if(key=="catalogueprev"||key=="cataloguenext"){catalogue.Step(key=="catalogueprev"?-1:1);Focus();return;}switch(key){case "frogger":SportsNavigation.LoadSport(SportsNavigation.Frog);break;case "avalanche":SportsNavigation.LoadSport(SportsNavigation.Avalanche);break;case "ninjawarrior":SportsNavigation.LoadSport(SportsNavigation.Ninja);break;case "hideandseek":SportsNavigation.LoadSport(SportsNavigation.Hide);break;case "hungryhaulers":SportsNavigation.LoadSport(SportsNavigation.Hauler);break;case "sheepherding":SportsNavigation.LoadSport(SportsNavigation.Herd);break;case "volleyball":SportsNavigation.LoadSport(SportsNavigation.Volley);break;case "freezetag":SportsNavigation.LoadSport(SportsNavigation.Freeze);break;case "magnetmayhem":SportsNavigation.LoadSport(SportsNavigation.Magnet);break;case "jousting":SportsNavigation.LoadSport(SportsNavigation.Joust);break;case "tetherball":SportsNavigation.LoadSport(SportsNavigation.Tether);break;case "floorislava":SportsNavigation.LoadSport(SportsNavigation.Lava);break;case "seesaw":SportsNavigation.LoadSport(SportsNavigation.Seesaw);break;case "kingofthehill":SportsNavigation.LoadSport(SportsNavigation.Hill);break;case "whackamole":SportsNavigation.LoadSport(SportsNavigation.Whack);break;case "balloon":SportsNavigation.LoadSport(SportsNavigation.Balloon);break;case "hotpotato":SportsNavigation.LoadSport(SportsNavigation.HotPotato);break;case "redlight":SportsNavigation.LoadSport(SportsNavigation.RedLight);break;case "snake":SportsNavigation.LoadSport(SportsNavigation.Snake);break;case "farefight":SportsNavigation.LoadSport(SportsNavigation.FareFight);break;case "trailerplug":SportsNavigation.LoadSport(SportsNavigation.TrailerPlug);break;case "skytow":SportsNavigation.LoadSport(SportsNavigation.SkyTow);break;case "danceoff":SportsNavigation.LoadSport(SportsNavigation.DanceOff);break;case "limbo":SportsNavigation.LoadSport(SportsNavigation.Limbo);break;case "kickball":SportsNavigation.LoadSport(SportsNavigation.Kickball);break;case "scrapheap":Show(4);break;case "scrapback":Show(1);break;case "pedestrianplowingcab":SportsNavigation.LoadSport(SportsNavigation.PedestrianPlowingCab);break;case "pedestrianplowing":SportsNavigation.LoadSport(SportsNavigation.PedestrianPlowing);break;case "derby":SportsNavigation.LoadSport(SportsNavigation.Derby);break;case "dodgeball":SportsNavigation.LoadSport(SportsNavigation.Dodgeball);break;case "logrolling":SportsNavigation.LoadSport(SportsNavigation.LogRolling);break;case "skee":SportsNavigation.LoadSport(SportsNavigation.Skee);break;case "tug":SportsNavigation.LoadSport(SportsNavigation.Tug);break;case "poker":SportsNavigation.LoadSport(SportsNavigation.Poker);break;case "beerpong":SportsNavigation.LoadSport(SportsNavigation.BeerPong);break;case "fieldgoal":SportsNavigation.LoadSport(SportsNavigation.FieldGoal);break;case "targetlaunch":SportsNavigation.LoadSport(SportsNavigation.TargetLaunch);break;case "sumo":SportsNavigation.LoadSport(SportsNavigation.Sumo);break;case "fishing":SportsNavigation.LoadSport(SportsNavigation.Fishing);break;case "bungee":SportsNavigation.LoadSport(SportsNavigation.Bungee);break;case "bog":SportsNavigation.LoadSport(SportsNavigation.Bog);break;case "buzkashi":SportsNavigation.LoadSport(SportsNavigation.Buzkashi);break;case "swing":SportsNavigation.LoadSport(SportsNavigation.Swing);break;case "parking":SportsNavigation.LoadSport(SportsNavigation.Parking);break;case "wife":SportsNavigation.LoadSport(SportsNavigation.Wife);break;case "mattress":SportsNavigation.LoadSport(SportsNavigation.Mattress);break;case "minefield":SportsNavigation.LoadSport(SportsNavigation.Minefield);break;case "play":Show(1);break;case "practice":SportsNavigation.BilliardsPractice=true;SportsNavigation.LoadSport(SportsNavigation.Billiards);break;case "billiards":SportsNavigation.BilliardsPractice=false;SportsNavigation.LoadSport(SportsNavigation.Billiards);break;case "dock":SportsNavigation.LoadSport(SportsNavigation.Dock);break;case "terrier":SportsNavigation.LoadSport(SportsNavigation.Terrier);break;case "keepawayfp":SportsNavigation.LoadSport(SportsNavigation.KeepawayCab);break;case "keepaway":SportsNavigation.LoadSport(SportsNavigation.Keepaway);break;case "curling":SportsNavigation.LoadSport(SportsNavigation.Curling);break;case "basejump":SportsNavigation.LoadSport(SportsNavigation.BaseJump);break;case "cheese":SportsNavigation.LoadSport(SportsNavigation.Cheese);break;case "cornhole":SportsNavigation.LoadSport(SportsNavigation.Cornhole);break;case "wallball":SportsNavigation.LoadSport(SportsNavigation.Wallball);break;case "airhockey":SportsNavigation.LoadSport(SportsNavigation.AirHockey);break;case "bowling":SportsNavigation.LoadSport(SportsNavigation.Bowling);break;case "hockey":SportsNavigation.LoadSport(SportsNavigation.Hockey);break;case "help":Show(2);break;case "settings":SettingsText();Show(3);break;case "back":Show(0);break;case "quit":Application.Quit();break;}}
 protected override void Update(){var modalCrew=GetComponent<SportsParticipantsMenu>();if(modalCrew!=null&&modalCrew.IsCustomizing)return;base.Update();bool back=SportsDeviceInput.KeyDown(Key.Escape);foreach(var p in Gamepad.all)back|=menuInput.Down(p,8);if(back&&Page!=0){var crew=GetComponent<SportsParticipantsMenu>();if(crew!=null&&Page==crew.page)crew.Action("peopleback");else if(crew!=null&&Page==crew.choicePage)crew.Action("peoplechooseback");else Show(Page==4?1:0);}}
}
}
